// Faire correspondre chaque page avec un salarié
const pages = $('extraire-texte-pdf').item.json.pages;
const salaries = $input.first().json;

const resultatsMatching = [];
const nonTrouves = [];
const emailsManquants = [];

for (const page of pages) {
  const salarie = salaries.find(s => s.nomPrenom === page.nomPrenom);

  if (!salarie) {
    nonTrouves.push(page.nomPrenom);
    resultatsMatching.push({
      ...page,
      statut: 'NON_TROUVE',
      email: null,
      inclure: false
    });
  } else if (!salarie.email) {
    emailsManquants.push(page.nomPrenom);
    resultatsMatching.push({
      ...page,
      statut: 'EMAIL_MANQUANT',
      email: null,
      idDossierDrive: salarie.idDossierDrive,
      inclure: true
    });
  } else {
    resultatsMatching.push({
      ...page,
      statut: 'OK',
      email: salarie.email,
      idDossierDrive: salarie.idDossierDrive,
      inclure: true
    });
  }
}

return [{
  json: {
    mapping: resultatsMatching,
    nonTrouves,
    emailsManquants,
    nbTotal: resultatsMatching.length,
    nbOk: resultatsMatching.filter(m => m.statut === 'OK').length,
    nbProblemes: nonTrouves.length + emailsManquants.length,
    fileId: $('extraire-texte-pdf').item.json.fileId,
    periode: $('validation-entree').item.json.periode
  }
}];
